// Entry module of the PIN guide page. The page itself is static HTML (generated by scripts/build-guide.mjs);
// this only wires the theme button, the language menu and the v1/v2 switch, which sets data-board on <main> (styles/guide.css hides the cards).
import { mountThemeToggle } from './theme.js';
import { loadLocale, guidePath } from './i18n.js';
import { mountLanguageMenu } from './language-menu.js';

const main = document.getElementById('main');
for (const input of document.querySelectorAll('input[name="board"]')) {
  input.addEventListener('change', () => { if (input.checked) main.dataset.board = input.value; });
}
const checked = document.querySelector('input[name="board"]:checked');
// Firefox restores the radio on reload without a change event, so read it once at start.
if (checked) main.dataset.board = checked.value;
// The guide's own text is static HTML; only the buttons need the page's main locale (labels, menu), as on the programmer page.
loadLocale().then(() => {
  mountThemeToggle(document.getElementById('btn-theme'));
  mountLanguageMenu(document.getElementById('btn-lang'), guidePath);
});
